/*
 * A194769  Sum of distinct nonzero sixth powers.
 * https://oeis.org/A194769
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the nth smallest sum of distinct nonzero sixth powers
 *            (OEIS A194769). The sequence is generated by enumerating all
 *            subset sums of the infinite set {k^6 : k ≥ 1} in increasing
 *            order. After n > 9108736851 the sequence is linear: a(n) = n +
 *            2037573096
 * Range:     u8 n <= 2, u16 n <= 24, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* A minimal binary heap for (sum,last) pairs.  The heap is global so that
   the enumeration can continue across successive calls to a(). */
typedef struct {
    seq_t sum;  /* current subset sum                        */
    idx_t last; /* index of the largest element in subset   */
} Node;

typedef struct {
    Node *data;
    size_t size;
    size_t capacity;
} Heap;

static void heap_init(Heap *h)
{
    h->size     = 0;
    h->capacity = 16;
    h->data     = (Node*)malloc(h->capacity * sizeof(Node));
}

static void heap_push(Heap *h, Node v)
{
    if (h->size == h->capacity) {
        h->capacity *= 2;
        h->data = (Node*)realloc(h->data, h->capacity * sizeof(Node));
    }
    size_t i = h->size++;
    h->data[i] = v;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (h->data[p].sum <= h->data[i].sum) break;
        Node tmp = h->data[p];
        h->data[p] = h->data[i];
        h->data[i] = tmp;
        i = p;
    }
}

static Node heap_pop(Heap *h)
{
    Node ret = h->data[0];
    --h->size;
    if (h->size > 0) {
        Node last = h->data[h->size];
        h->data[0] = last;
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            size_t r = l + 1;
            size_t smallest = i;
            if (l < h->size && h->data[l].sum < h->data[smallest].sum)
                smallest = l;
            if (r < h->size && h->data[r].sum < h->data[smallest].sum)
                smallest = r;
            if (smallest == i) break;
            Node tmp = h->data[i];
            h->data[i] = h->data[smallest];
            h->data[smallest] = tmp;
            i = smallest;
        }
    }
    return ret;
}

/* Powers of six: powers[i] = (i+1)^6, for i = 0,1,2,... */
#define MAX_POWERS 512
static seq_t powers[MAX_POWERS];
static size_t powers_len = 0;
static int powers_init = 0;

static void init_powers(void)
{
    if (powers_init) return;
    powers_len = 0;
    /* pre‑compute enough sixth powers (k = 1..200) – this covers all sums
       needed for the values that our function is expected to return. */
    for (idx_t k = 1; k <= 200 && powers_len < MAX_POWERS; ++k) {
        seq_t p = 1;
        for (idx_t e = 0; e < 6; ++e)
            p *= (seq_t)k;
        powers[powers_len++] = p;
    }
    powers_init = 1;
}

/* Global table of already produced terms of the sequence. */
static seq_t *seq_table = NULL;
static size_t seq_len   = 0;   /* number of terms stored */
static size_t seq_cap   = 0;

/* Global heap used by the enumeration algorithm. */
static Heap heap;
static int heap_initialized = 0;

/* Grow the table until it contains at least 'target' terms. */
static void ensure_computed(idx_t target)
{
    if (seq_len >= target) return;
    init_powers();

    if (!heap_initialized) {
        heap_initialized = 1;
        heap_init(&heap);
        /* Seed the heap with the first subset: {powers[0]} */
        Node start = {powers[0], 0};
        heap_push(&heap, start);
    }

    while (seq_len < target) {
        Node cur = heap_pop(&heap);
        /* Append the newly generated sum */
        if (seq_len == seq_cap) {
            seq_cap = seq_cap == 0 ? 16 : seq_cap << 1;
            seq_table = (seq_t*)realloc(seq_table, seq_cap * sizeof(seq_t));
        }
        seq_table[seq_len++] = cur.sum;

        /* Generate the two successor states for this node. */
        if (cur.last + 1 < powers_len) {
            size_t nxt = cur.last + 1;
            Node add     = {cur.sum + powers[nxt], nxt};
            Node replace = {cur.sum - powers[cur.last] + powers[nxt], nxt};
            heap_push(&heap, add);
            heap_push(&heap, replace);
        }
    }
}

/* --------------------  Sequence function  -------------------- */

seq_t a(idx_t n)
{
    /* For very large n the sequence is linear; use the formula directly. */
    static const idx_t THRESHOLD = 9108736851ULL;
    static const seq_t ADDEND   = 2037573096ULL;
    if (n > THRESHOLD) {
        return (seq_t)n + (seq_t)ADDEND;
    }

    /* Generate terms up to the requested index. */
    ensure_computed(n);
    return seq_table[n-1];
}
